argv:
$ErrorActionPreference='Stop';
$repo='E:\WebAIBridge';
function GitBlobSha([byte[]]$bytes){
  $prefix=[Text.Encoding]::ASCII.GetBytes(('blob '+$bytes.Length+[char]0));
  $all=New-Object byte[] ($prefix.Length+$bytes.Length);
  [Array]::Copy($prefix,0,$all,0,$prefix.Length);
  [Array]::Copy($bytes,0,$all,$prefix.Length,$bytes.Length);
  $sha=[Security.Cryptography.SHA1]::Create();
  return (($sha.ComputeHash($all)|ForEach-Object{$_.ToString('x2')}) -join '');
}
$out=@();
foreach($rel in @('app/scripts/operator-lifecycle-r40.ps1','app/scripts/pause-all-r40.cmd','app/scripts/pause-browser-r40.cmd','app/scripts/resume-attach-r40.cmd','app/scripts/resume-managed-r40.cmd')){
  $path=Join-Path $repo $rel;
  $raw=[IO.File]::ReadAllBytes($path);
  $hasBom=($raw.Length-ge 3 -and $raw[0]-eq 239 -and $raw[1]-eq 187 -and $raw[2]-eq 191);
  $offset=if($hasBom){3}else{0};
  $text=[Text.Encoding]::UTF8.GetString($raw,$offset,$raw.Length-$offset);
  $crlf=([string][char]13)+([string][char]10);
  $lf=[string][char]10;
  $normText=$text.Replace($crlf,$lf);
  $norm=[Text.Encoding]::UTF8.GetBytes($normText);
  $head=([string](git.exe -C $repo rev-parse ('HEAD:'+$rel))).Trim();
  $noBomNorm=GitBlobSha $norm;
  $out += [pscustomobject]@{
    file=$rel; hasUtf8Bom=$hasBom;
    firstBytes=(($raw|Select-Object -First 6|ForEach-Object{$_.ToString('X2')}) -join ' ');
    headBlob=$head; normalizedNoBomBlob=$noBomNorm;
    matchesHeadAfterBomStrip=($head -eq $noBomNorm)
  };
}
$out|ConvertTo-Json -Depth 4 -Compress
